//#region src/lib/analytics.ts
function pushDataLayer(event) {
	if (typeof window === "undefined") return;
	window.dataLayer = window.dataLayer ?? [];
	window.dataLayer.push(event);
}
function trackLeadCapture() {
	pushDataLayer({
		event: "lead_capture",
		content_name: "5-day-gut-health-guide"
	});
	window.fbq?.("track", "Lead", { content_name: "5-Day Gut Health & Morning Routine Guide" });
}
function trackProductClick(productName) {
	pushDataLayer({
		event: "product_click",
		product_name: productName
	});
	window.fbq?.("track", "ViewContent", {
		content_name: productName,
		content_type: "product"
	});
}
function trackShopClick(productName) {
	pushDataLayer({
		event: "initiate_checkout",
		product_name: productName
	});
	window.fbq?.("track", "InitiateCheckout", { content_name: productName });
}
function trackGuideView() {
	pushDataLayer({
		event: "guide_view",
		content_name: "5-day-gut-health-guide"
	});
	window.fbq?.("trackCustom", "GuideView");
}
