//#region src/lib/bag.ts
var STORAGE_KEY = "gibson-wellness-bag";
var LEAD_KEY = "gibson-wellness-lead";
function readJson(key, fallback) {
	if (typeof window === "undefined") return fallback;
	try {
		const raw = window.localStorage.getItem(key);
		return raw ? JSON.parse(raw) : fallback;
	} catch {
		return fallback;
	}
}
var useBag = create((set, get) => ({
	items: [],
	hydrated: false,
	hasLead: false,
	hydrate: () => {
		if (get().hydrated) return;
		set({
			items: readJson(STORAGE_KEY, []),
			hasLead: Boolean(readJson(LEAD_KEY, null)),
			hydrated: true
		});
	},
	add: (product) => {
		const items = get().items.some((item) => item.id === product.id) ? get().items : [...get().items, {
			id: product.id,
			title: product.title,
			price: product.price,
			image: product.image,
			href: product.href
		}];
		set({ items });
		window.localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
	},
	remove: (id) => {
		const items = get().items.filter((item) => item.id !== id);
		set({ items });
		window.localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
	},
	setLead: (email) => {
		window.localStorage.setItem(LEAD_KEY, email.trim().toLowerCase());
		set({ hasLead: true });
	}
}));
